-- Reference layer from the municipal GIS (Tel Aviv's bicycle docking
-- facilities in private building yards), shown as an optional admin-only
-- overlay on the admin map. Admin-only like every other non-public table
-- here, via the same has_role() RLS pattern. Data exported from the
-- municipal GIS portal on 2026-11-04 (2318 points).
CREATE TABLE public.bicycle_docking_private_yards (
  id integer PRIMARY KEY,
  address text NOT NULL,
  spaces integer,
  latitude double precision NOT NULL,
  longitude double precision NOT NULL
);

ALTER TABLE public.bicycle_docking_private_yards ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Admins can view docking stations"
ON public.bicycle_docking_private_yards
FOR SELECT
USING (has_role(auth.uid(), 'admin'::app_role));

